// Nie edytuj ręcznie; regeneruj z facts.
export const KB = [{"id": "b1-1131", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 1.1.3.1", "why": "Zwolnienia z charakteru operacji transportowych 1.1.3.1: osoby fizyczne przewożące w małych fabrycznych opakowaniach (np. paliwo do 240 l), przewóz o charakterze pomocniczym, przewóz nadzorowany przez służby ratunkowe, przewóz w celu ratowania życia lub ochrony środowiska, przewóz próżnych zbiorników transportowych."}, {"id": "b1-1132-gazy", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 1.1.3.2", "why": "Zwolnienia dla gazów 1.1.3.2: gazy w zbiornikach pojazdu do napędu; gazy w zbiornikach przewożonych pojazdów — wartość energetyczna max 54 000 MJ. Łączna objętość: 1080 kg dla LNG i CNG, 2250 l dla LPG. Także gazy w wyposażeniu (gaśnice, napompowane koła), w żywności, w sprzęcie sportowym."}, {"id": "b1-1133-paliwo", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 1.1.3.3", "why": "Zwolnienie 1.1.3.3 — paliwo w zbiornikach pojazdu służące do jego napędu lub pracy wyposażenia: do 1500 l na jednostkę transportową, nie więcej niż 500 l na przyczepie. W zbiornikach dodatkowych (kanistrach) nie więcej niż 60 l."}, {"id": "b1-1136-gasnica", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6 / 8.1.4", "why": "Pojazd przewożący towary niebezpieczne na zwolnieniu 1.1.3.6 musi być wyposażony w 1 gaśnice 2 kg typu ABC."}, {"id": "b1-1136", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6", "why": "Zwolnienie 1.1.3.6 (tzw. 1000 pkt) — pod uwagę bierze się ilość towaru na jednostce transportowej. WYMAGANE: opakowania certyfikowane i oznakowane, gaśnica 2 kg ABC z data przeglądu, prawidłowy dokument przewozowy, szkolenie stanowiskowe. NIE MUSISZ: oznakowywać pojazdu tablicami, mieć zaświadczenia ADR, instrukcji pisemnej, wyposażenia (skrzynki ADR), stosować się do znaków drogowych ADR, wyznaczać DGSA, przestrzegać zakazu przewozu pasażerów."}, {"id": "b1-def", "block": 1, "blockName": "Wymagania ogólne", "topic": "Podstawy prawne", "adrRef": "ADR 1.1", "why": "Umowa ADR powstała w 1957 r. w Genewie. Składa się z 2 załączników A i B. Nowelizowana co 2 lata."}, {"id": "b1-dgsa", "block": 1, "blockName": "Wymagania ogólne", "topic": "Podstawy prawne", "adrRef": "ADR 1.8.3", "why": "DGSA to doradca ds. bezpieczeństwa. Powinna go wyznaczyć każda firma pakująca, ładująca, transportująca lub rozładowująca towary niebezpieczne. Kara za niewyznaczenie: 5000 PLN."}, {"id": "b1-droga-uprawnienia", "block": 1, "blockName": "Wymagania ogólne", "topic": "Zakres uprawnień", "adrRef": "ADR 8.2 / ustawa PL", "why": "Droga do uprawnień ADR: 1) kurs w akredytowanym ośrodku (podstawowy, a dla cystern/klasy 1/klasy 7 dodatkowo specjalistyczny), 2) egzamin państwowy przed Urzędem Marszałkowskim, 3) zaświadczenie ADR wydawane przez marszałka, 4) ważność 5 lat. Uprawnień nie zdobywa się z aplikacji — ta apka przygotowuje Cię do egzaminu."}, {"id": "b1-egzamin-prog", "block": 1, "blockName": "Wymagania ogólne", "topic": "Zakres uprawnień", "adrRef": "ADR 8.2.2 / ustawa PL", "why": "Egzamin państwowy to test jednokrotnego wyboru nadzorowany przez Urząd Marszałkowski. Próg zaliczenia to co najmniej dwie trzecie poprawnych odpowiedzi. Kurs podstawowy: 30 pytań (próg 20). Kurs cysterny: 18 pytań."}, {"id": "b1-eq", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 3.5", "why": "Ilości wyłączone (EQ), przepis 3.5: materiały w opakowaniach wewnętrznych nie mogą być większe niż 1 kg (1000 g) lub 1 litr (1000 ml). Opakowanie NIE musi być certyfikowane, brak nalepek ostrzegawczych. Wymaga szkolenia stanowiskowego, NIE kursu ADR. W dokumencie zapis \"Towary niebezpieczne w ilościach wyłączonych\" oraz liczba sztuk przesyłek."}, {"id": "b1-inne-galezie", "block": 1, "blockName": "Wymagania ogólne", "topic": "Podstawy prawne", "adrRef": "RID / ADN / IMDG / ICAO TI", "why": "Poza ADR (drogowy) istnieją: RID — kolejowy, ADN — śródlądowy, IMDG — morski, ICAO TI — lotniczy."}, {"id": "b1-jtr", "block": 1, "blockName": "Wymagania ogólne", "topic": "Jednostka i sposoby przewozu", "adrRef": "ADR 1.2.1", "why": "Jednostka transportową to pojazd silnikowy z przyczepa lub bez, albo ciągnik z naczepa. Ciągnik + naczepa = JEDNA jednostka, choc to dwa pojazdy. Ważne przy liczeniu wyposażenia i wyłączeń."}, {"id": "b1-kat0", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6.3", "why": "Dla towarów kategorii transportowej 0 KAŻDA ilość oznacza pełny ADR — limit wynosi 0, nie ma mnożnika. Dotyczy to także próżnych opakowań po towarach kategorii 0."}, {"id": "b1-kat1-wyjatek", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6.3", "why": "W kategorii transportowej 1 występuje wyjątek: dla UN 0081, 0082, 0084, 0241, 0331, 0332, 0482, 1005 i 1017 maksymalna ilość całkowita na jednostkę transportową wynosi 50 kg, a mnożnik to x20 (zamiast standardowych 20 i x50)."}, {"id": "b1-kat4", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6.3", "why": "Kategoria transportową 4 — każda ilość \"na wyłączeniu\", mnożnik 0, bez ograniczeń. Należą tu: próżne opakowania po towarach niebezpiecznych (z wyłączeniem tych z kategorii 0), materiały wybuchowe 1.4S oraz WSZYSTKIE butle po gazach. Butle po gazach może przewozić kierowca bez zaświadczenia ADR."}, {"id": "b1-kategorie-transportowe", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6.3 / kol. 15", "why": "Jest 5 kategorii transportowych (0-1-2-3-4). Kategorie transportowe to NIE klasy ani grupy pakowania. Limity na jednostkę transportową: kąt. 0 = 0 (zawsze pełny ADR), kąt. 1 = 20 (mnożnik x50), kąt. 2 = 333 (x3), kąt. 3 = 1000 (x1), kąt. 4 = bez ograniczeń (mnożnik 0). Kategorie sprawdza się w kolumnie 15 tabeli A."}, {"id": "b1-kurs-cysterny-prog", "block": 1, "blockName": "Wymagania ogólne", "topic": "Zakres uprawnień", "adrRef": "ADR 8.2.1", "why": "Kurs specjalistyczny ADR cysterny jest wymagany dla cystern powyżej 1 m3 (1000 l). Pozwala przewozić wszystkie klasy poza 1 i 7 w cysternach."}, {"id": "b1-lq-oznakowanie-pojazdu", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 3.4.13", "why": "Jednostki transportowe powyżej 12 t DMC przewożące powyżej 8 t brutto towarów LQ muszą być oznakowane znakiem LQ z przodu i tyłu pojazdu (250 x 250 mm). Nadawca musi poinformować przewoźnika o całkowitej ilości LQ. Oznakowanie zamienne z tablicami pomarańczowymi."}, {"id": "b1-lq-tunel-e", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 1.9.5 / 3.4", "why": "Jednostki transportowe oznakowane znakiem LQ (powyżej 8 t brutto) NIE MOGĄ wjeżdżać do tunelu kategorii E."}, {"id": "b1-lq", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 3.4", "why": "Ilości ograniczone (LQ), przepis 3.4: opakowania kombinowane max 5 kg/l wewnętrzne i 30 kg/l opakowanie. Można przewozić do ładowności auta. Oznakowanie: kwadrat obrócony o 45 stopni z czarno-białymi trójkątami."}, {"id": "b1-luzem-przepisy", "block": 1, "blockName": "Wymagania ogólne", "topic": "Jednostka i sposoby przewozu", "adrRef": "ADR kol. 10/17 Tabeli A", "why": "Przewóz luzem = materiał sypki bez opakowania, wprost do skrzyni/kontenera. Wolno go wieźć TYLKO wtedy, gdy tabela A na to pozwala — w kolumnie 10 lub 17 musi widnieć kod BK albo VC. BK (Bulk Container) = dozwolony określony typ kontenera do przewozu luzem. VC (Vehicle/Container) = warunki, w jakich wolno wieźć luzem danym pojazdem lub kontenerem. Dla kontrastu: kody P (np. P200, P900) to instrukcje PAKOWANIA — dotyczą przewozu w sztukach przesyłki, nie luzem. Kody S (np. S1, S2) to przepisy dot. bezpieczeństwa przewozu. Jeśli w kolumnach luzem NIE ma BK ani VC — przewóz luzem jest zakazany."}, {"id": "b1-mnozniki", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6.4", "why": "Mnożniki kategorii transportowych: kąt. 1 = x50, kąt. 2 = x3, kąt. 3 = x1, kąt. 4 = 0. Suma iloczynów nie może przekroczyć 1000."}, {"id": "b1-nadawca", "block": 1, "blockName": "Wymagania ogólne", "topic": "Uczestnicy przewozu", "adrRef": "ADR 1.4.2.1", "why": "Nadawca: upewnia się że towary są sklasyfikowane i dopuszczone do przewozu, zaopatruje przewoźnika w dokumenty przewozowe, używa wyłącznie dopuszczonych opakowań/DPPL/cystern ze znakami ADR, odpowiada za oznakowanie kontenerów. Nadawca działa PRZED przewozem i na papierze (klasyfikacja, dokumenty) — nie mylić z załadowca, który fizycznie układa towar na pojeździe."}, {"id": "b1-odbiorca", "block": 1, "blockName": "Wymagania ogólne", "topic": "Uczestnicy przewozu", "adrRef": "ADR 1.4.2.3", "why": "Odbiorca: nie opóźnia przyjęcia towarów bez konieczności, sprawdza po rozładunku spełnienie wymagań ADR. Kontener może zwrócić przewoźnikowi dopiero po usunięciu naruszenia. Haczyk: odbiorca PRZYJMUJE towar — fizyczne zdejmowanie, czyszczenie i odkażanie po rozładunku to obowiązek rozładowcy, nie odbiorcy (choc często to ta sama firma)."}, {"id": "b1-odstepstwa", "block": 1, "blockName": "Wymagania ogólne", "topic": "Podstawy prawne", "adrRef": "ADR 1.5", "why": "Strony umowy mogą wprowadzać umowy specjalne dopuszczające odstępstwa od przepisów. Odstępstwa nie mogą być dłuższe niż 5 lat."}, {"id": "b1-prozne-oznakowanie", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 5.1.3", "why": "Próżne, NIEOCZYSZCZONE opakowania pozostają oznakowane tak jak w stanie ładownym. NIE usuwamy nalepek ostrzegawczych ani numerów UN."}, {"id": "b1-przepisy-szczegolne", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 3.3", "why": "Zwolnienia z przepisów szczególnych: 598 — akumulatory, 168 — przewóz azbestu, 188 — akumulatory litowe zawarte w urządzeniach (nie podlega ADR)."}, {"id": "b1-przewoznik", "block": 1, "blockName": "Wymagania ogólne", "topic": "Uczestnicy przewozu", "adrRef": "ADR 1.4.2.2", "why": "Przewoźnik: upewnia się WZROKOWO czy pojazd i ładunek nie mają oczywistych wad, wycieków, nieszczelności, braków w wyposażeniu; sprawdza czy pojazd nie jest nadmiernie załadowany; sprawdza nalepki, znaki i tablice; sprawdza wyposażenie."}, {"id": "b1-rodzaje-przewozu", "block": 1, "blockName": "Wymagania ogólne", "topic": "Jednostka i sposoby przewozu", "adrRef": "ADR 1.2.1", "why": "Trzy sposoby przewozu: w sztukach przesyłki (opakowania), luzem (nieopakowane materiały stałe), w cysternie."}, {"id": "b1-role-rozroznianie", "block": 1, "blockName": "Wymagania ogólne", "topic": "Uczestnicy przewozu", "adrRef": "ADR 1.4", "why": "Najczęstsza pomyłka to mylenie ROL, które brzmią podobnie. Klucz po czasowniku: nadawca KLASYFIKUJE i daje dokumenty (działa PRZED przewozem, na papierze). Przewoźnik OGLĄDA wzrokowo pojazd tuż przed jazdą. Załadowca UKŁADA sztuki na pojeździe i pilnuje segregacji. Napełniający LEJE do cystern. Rozładowca CZYŚCI po rozładunku. Odbiorca PRZYJMUJE (nie opóźnia). Zapamiętaj: klasyfikuje=nadawca, ogląda=przewoźnik, układa=załadowca, leje=napełniający, czyści=rozładowca, przyjmuje=odbiorca."}, {"id": "b1-rozladowca", "block": 1, "blockName": "Wymagania ogólne", "topic": "Uczestnicy przewozu", "adrRef": "ADR 1.4.3.7", "why": "Rozładowca: sprawdza czy rozładowano właściwe towary (porównanie dokumentu ze sztuka przesyłki), sprawdza uszkodzenia, po rozładunku usuwa pozostałości z zewnętrznej powierzchni, zamyka zawory, zapewnia oczyszczenie i odkażenie. Z całkowicie oczyszczonego kontenera ZDEJMUJE nalepki i tablice."}, {"id": "b1-szkolenie", "block": 1, "blockName": "Wymagania ogólne", "topic": "Zakres uprawnień", "adrRef": "ADR 1.3 / 8.2", "why": "Korzystając ze wszystkich wyłączeń kierowca NIE musi posiadać zaświadczenia ADR. Powinien przejść na koszt pracodawcy szkolenie stanowiskowe (wg 1.3), inne niż kurs ADR."}, {"id": "b1-uczestnicy", "block": 1, "blockName": "Wymagania ogólne", "topic": "Uczestnicy przewozu", "adrRef": "ADR 1.4", "why": "Sześciu uczestników przewozu i ich JEDEN kluczowy obowiązek: nadawca (klasyfikuje i dopuszcza do przewozu, daje dokumenty), przewoźnik (sprawdza wzrokowo pojazd i ładunek przed jazdą), załadowca (układa sztuki na pojeździe, pilnuje segregacji), napełniający (napełnia cysterny), rozładowca (sprawdza i czyści po rozładunku), odbiorca (nie opóźnia przyjęcia). Uczysz się po czasowniku — każda rola ma inny."}, {"id": "b1-ustawa-pl", "block": 1, "blockName": "Wymagania ogólne", "topic": "Podstawy prawne", "adrRef": "Dz.U. 2011 nr 227 poz. 1367", "why": "W Polsce obowiązuje Ustawa o przewozie towarów niebezpiecznych z 19.08.2011 (Dz.U. 2011 nr 227 poz. 1367)."}, {"id": "b1-wartosc-energetyczna", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 1.1.3.2 uwaga 1", "why": "Wartości energetyczne paliw: olej napędowy 36 MJ/l, benzyna silnikowa 32 MJ/l, gaz ziemny/biogaz 35 MJ/Nm3, LPG 24 MJ/l, etanol 21 MJ/l, olej napędowy bio 33 MJ/l, paliwo emulsyjne 32 MJ/l, wodór 11 MJ/Nm3."}, {"id": "b1-waznosc", "block": 1, "blockName": "Wymagania ogólne", "topic": "Zakres uprawnień", "adrRef": "ADR 8.2.2.8", "why": "Zaświadczenie o przeszkoleniu kierowcy wydaje się na okres 5 lat. W ostatnim roku ważności można je przedłużyć na kolejny okres."}, {"id": "b1-wejscie-przepisow", "block": 1, "blockName": "Wymagania ogólne", "topic": "Podstawy prawne", "adrRef": "ADR 1.6", "why": "Nowe przepisy ADR wchodzą zawsze 1 stycznia w roku nieparzystym. Do końca czerwca obowiązuje okres przejściowy — można używać starej lub nowej wersji."}, {"id": "b1-zakres-podstawowy", "block": 1, "blockName": "Wymagania ogólne", "topic": "Zakres uprawnień", "adrRef": "ADR 8.2.1", "why": "ADR podstawowy pozwala przewozić wszystkie klasy poza 1 i 7 w sztukach przesyłki oraz luzem, a także w cysternach stałych i odejmowalnych do 1000 l i kontenerach-cysternach do 3000 l. Taki przewóz NIE wymaga świadectwa dopuszczenia pojazdu (\"czerwonego paska\")."}, {"id": "b1-zaladowca", "block": 1, "blockName": "Wymagania ogólne", "topic": "Uczestnicy przewozu", "adrRef": "ADR 1.4.3.1", "why": "Załadowca to ten, kto UMIESZCZA zapakowany towar (sztuki przesyłki, kontenery) NA pojazd — nie mylić z napełniającym (ten napełnia cysterny) ani z pakującym (ten wkłada towar do opakowań). Załadowca: przekazuje do przewozu tylko towar dopuszczony, sprawdza czy opakowania nie są uszkodzone, przestrzega zakazów ładowania razem (segregacja) i zasad mocowania. Haczyk: załadowca patrzy na STAN opakowania i zgodność załadunku, a nie klasyfikuje towaru (to nadawca)."}, {"id": "b1-zaswiadczenie-wydanie", "block": 1, "blockName": "Wymagania ogólne", "topic": "Zakres uprawnień", "adrRef": "ADR 8.2.2.8 / ustawa PL", "why": "Po zdanym egzaminie marszałek wydaje zaświadczenie ADR (plastikowa karta) w ciągu 14 dni; w praktyce dociera pocztą w 1-3 tygodnie. Ważność 5 lat. Żeby przedłużyć, w ostatnim roku ważności robisz kurs doskonalący i ponownie zdajesz egzamin, zanim dokument wygaśnie."}, {"id": "b2-grupy-pakowania", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR 2.1.1.3", "why": "Grupy pakowania określają natężenie zagrożenia dominującego: I — zagrożenie duże, II — średnie, III — małe. Grup pakowania NIE MAJĄ klasy 1, 2, 5.2, 6.2, 7 oraz przedmioty."}, {"id": "b2-ino", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR 3.1.2.8", "why": "Litery I.N.O. po nazwie oznaczają \"inaczej nie określony\". Wymaga się wtedy uzupełnienia o nazwy techniczne, np. UN 1964 WĘGLOWODORY GAZOWE, MIESZANINA SPRĘŻONA I.N.O (zawiera wodór i argon) 2.1 (B/D)."}, {"id": "b2-klasa3-temp", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 2.2.3", "why": "Klasa 3 — materiały ciekłe zapalne o temperaturze zapłonu nie wyższej niż 60 stopni C, np. UN 1202, UN 1203. Uwaga: unikać zagłębień terenu."}, {"id": "b2-klasa9-temp", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 2.2.9", "why": "Klasa 9 obejmuje m.in. azbest (wdychany w postaci drobnego pyłu), materiały w podwyższonej temperaturze — stałe powyżej 240 st. C, ciekłe powyżej 100 st. C, akumulatory litowe, przedmioty ratownicze, materiały zagrażające środowisku wodnemu."}, {"id": "b2-klasyfikacja-kto", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR czesc 2", "why": "Za klasyfikację odpowiada PRODUCENT, NADAWCA oraz Instytut Przemysłu Organicznego (IPO). Dla klasy 7 — Państwowa Agencja Atomistyki (PAA)."}, {"id": "b2-kod-opakowania-xyz", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt opakowania", "adrRef": "ADR 6.1.2", "why": "Litera na drugim miejscu kodu opakowania wskazuje, dla której grupy pakowania może być użyte: X — dla I, II, III GP; Y — dla II, III GP; Z — tylko dla III GP."}, {"id": "b2-nalepka-9a", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 5.2.2.2", "why": "Nalepka 9A jest stosowana dla numerów UN 3090, UN 3091, UN 3480, UN 3481 — ogniwa i akumulatory litowe."}, {"id": "b2-nalepka-wymiary", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt opakowania", "adrRef": "ADR 5.2.2.2", "why": "Nalepka wskazująca zagrożenie na sztuce przesyłki ma rozmiar 100 mm x 100 mm. Może być więcej niż jedna — zagrożenie dominujące i dodatkowe."}, {"id": "b2-nie-podlega-adr", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 3.3 SP 188", "why": "Nie podlegają ADR: akumulatory i ogniwa litowe wg przepisu 188, pojazdy poddane fumigacji (zagrożenie uduszeniem), czynniki chłodzące np. UN 1845 suchy lód (zagrożenie uduszeniem)."}, {"id": "b2-numer-cyfry", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.3", "why": "Cyfry numeru rozpoznawczego zagrożenia: 2 — emisja gazu spowodowana ciśnieniem lub reakcja chemiczna, 3 — zapalność materiałów ciekłych i gazów, 4 — zapalność materiałów stałych, 5 — działanie utleniające, 6 — działanie trujące lub ryzyko zakażenia, 7 — działanie promieniotwórcze, 8 — działanie żrące, 9 — ryzyko samorzutnej i gwałtownej reakcji."}, {"id": "b2-numer-podwojenie", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.3", "why": "Powtórzenie cyfry wskazuje na nasilenie oznaczonego ta cyfra zagrożenia, np. 33 = materiał łatwo zapalny ciekły (temperatura zapłonu niższa niż 23 st. C)."}, {"id": "b2-numer-x", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.3", "why": "Litera X przed numerem rozpoznawczym zagrożenia oznacza niebezpieczna reakcje z wodą. Woda może być stosowana jedynie za zgoda specjalistów. UWAGA: nie mylić z X w kodzie opakowania, który określa mocne opakowanie do I, II, III grupy pakowania."}, {"id": "b2-numer-zero", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.3", "why": "Jeśli w numerze rozpoznawczym zagrożenia występuje 0 (zero), to zawsze na drugiej pozycji. Oznacza, ze NIE ma zwiększenia zagrożenia ani zagrożenia dodatkowego, a towar zwykle należy do II lub III grupy pakowania. Nie dotyczy gazów."}, {"id": "b2-numery-przyklady", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.3", "why": "Przykłady odczytu: 20 = gaz duszący lub niestwarzający zagrożenia dodatkowego, 23 = gaz palny, 26 = gaz trujący, 30 = materiał zapalny ciekły (23-60 st. C), 33 = materiał łatwo zapalny ciekły (poniżej 23 st. C), 80 = materiał żrący lub słabo żrący, 88 = materiał silnie żrący."}, {"id": "b2-numery-specjalne", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.3", "why": "Następujące zestawienia cyfr mają znaczenie specjalne: 22, 323, 333, 362, 382, 423, 44, 446, 462, 482, 539, 606, 623, 642, 823, 842, 90 i 99. Przykłady: 90 = materiał zagrażający środowisku, 99 = różne materiały niebezpieczne przewożone w podwyższonej temperaturze, 333 = materiał piroforyczny ciekły, 606 = materiał zakaźny."}, {"id": "b2-opakowania-waznosc", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt opakowania", "adrRef": "ADR 4.1.1.15", "why": "W większości wypadków (DPPL, kanistry, bębny) opakowania mogą być używane przez 5 lat od daty produkcji. Po 2,5 roku powinno być przeprowadzone badanie. Data produkcji zapisana jako cyfry miesiąca i roku, np. 07 21 = lipiec 2021, używany do lipca 2026."}, {"id": "b2-overpack", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt opakowania", "adrRef": "ADR 5.1.2", "why": "Jeśli używamy opakowania zbiorczego (skrzyni, klatki, palety) i nalepki lub numery UN nie są widoczne na zewnątrz, należy je ponowić. Gdy w opakowaniu są 2 rodzaje towaru (np. klasy 3 i 8), na zewnątrz muszą być wszystkie wzory nalepek (3 i 8). Jeśli nalepka jest ta sama dla wszystkich opakowań, wystarczy na palecie 1 nalepka. Należy umieścić napis OPAKOWANIE ZBIORCZE — OVERPACK (język kraju nadania i angielski lub niemiecki lub francuski)."}, {"id": "b2-oznakowanie-sztuki", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt opakowania", "adrRef": "ADR 5.2", "why": "Na każdej sztuce przesyłki musi znajdować się: numer UN przewożonego towaru, znak certyfikacji opakowania (symbol ONZ — litery \"un\" w kołku), nalepka wskazująca zagrożenie (100x100 mm), prawidłowa nazwa przewozowa (dla klas 1, 2, 7), strzałki kierunkowe nr 11 dla opakowań z naczyniami wewnętrznymi z materiałami ciekłymi."}, {"id": "b2-pietrowanie", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt opakowania", "adrRef": "ADR 6.5.2.2.2", "why": "Piętrowanie towarów niebezpiecznych jest dopuszczone, jeśli odpowiednie oznakowanie na opakowaniu wskazuje na taka możliwość (rys. 6.5.2.2.2.1 — DPPL przeznaczony do spietrzania, z podanym max obciążeniem w kg; rys. 6.5.2.2.2.2 — DPPL NIE przeznaczony do spietrzania)."}, {"id": "b2-podklasy2", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 2.2.2", "why": "Klasa 2 (gazy): 2.1 gazy palne, 2.2 gazy niepalne i nietrujące (mogą być duszące), 2.3 gazy trujące. Zagrożenie dominujące: wysokie ciśnienie, emisja gazu, odmrożenia, wybuch przy ogrzaniu."}, {"id": "b2-podklasy4", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 2.2.41-43", "why": "Klasa 4: 4.1 materiały zapalne stałe, samoreaktywne, polimeryzujące i wybuchowe odczulone stałe; 4.2 materiały podatne na samozapalenie (piroforyczne, tytan, rozdrobnione metale, fosfor biały); 4.3 materiały wytwarzające w zetknięciu z wodą gazy palne — muszą być przewożone w pojazdach zamkniętych."}, {"id": "b2-podklasy5", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 2.2.51-52", "why": "Klasa 5: 5.1 materiały utleniające — wzmagają palenie, same nie muszą się palić, nie mieszać z materiałami zapalnymi (np. trocinami); 5.2 nadtlenki organiczne typu A-F, niektóre mogą być wybuchowe."}, {"id": "b2-podklasy6", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 2.2.61-62", "why": "Klasa 6: 6.1 materiały trujące — zagrożenie śmiertelnym zatruciem przez połknięcie, wdychanie lub przez skórę; 6.2 materiały zakaźne — odpady medyczne, kliniczne, szpitalne, wirusy, bakterie, priony. UWAGA: NIE występują jednocześnie zakaźne i trujące."}, {"id": "b2-tablice-gladkie", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2", "why": "Tablice odblaskowe pomarańczowe mają wymiary 300 x 400 mm (+/- 10%) z czarna ramka o szerokości 15 mm. Tablice powinny przetrwać w pożarze 15 minut. Dopuszcza się tablice 300 x 120 mm (obramowanie 10 mm) w pojazdach bez miejsca na standardowa, np. osobowych. Tablic gładkich używa się zwykle przy przewozie w sztukach przesyłki."}, {"id": "b2-tablice-ramka", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.2.1", "why": "Tablica standardowa 300 x 400 mm ma czarna ramkę o szerokości 15 mm. Tablica mała 300 x 120 mm ma obramowanie 10 mm."}, {"id": "b2-temp-kontrolowana", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 7.1.7", "why": "Klasy 4.1 i 5.2 mogą wymagać temperatury kontrolowanej podczas przewozu (reakcja egzotermiczna). Wymagana jest możliwość sprawdzenia temperatury oraz procedura postępowania. Termometr z 2 czujnikami. Temperaturę sprawdza się co 4-6 h i rejestruje. Należy określić procedury na wypadek utraty możliwości utrzymania temperatury."}, {"id": "b2-un-pozycje", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR 3.1.2", "why": "Numer UN (nazywany też numerem ONZ) to czterocyfrowy numer rozpoznawczy. Może być przypisany do JEDNEJ substancji, np. UN 1090 ACETON, albo do POZYCJI GRUPOWEJ — kilku towarów o podobnych właściwościach, np. UN 1263 FARBA."}, {"id": "b2-zagrozenie-dodatkowe", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR 2.1.1.2", "why": "Zagrożenie dodatkowe określane jest kodem literowym, np. F — palne, T — trujące. Jest to DRUGA nalepka w dokumencie przewozowym (kod klasyfikacyjny)."}, {"id": "b2-zagrozenie-dominujace", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR 2.1.3.10", "why": "Zagrożenie dominujące przypisuje towar do jednej z 13 klas (licząc podklasy osobno) — jest to PIERWSZA nalepka. Nazwę klasy można znaleźć powyżej każdej z nalepek w instrukcji pisemnej. Klasa 2 (gazy) ma kilka nalepek."}, {"id": "b3-numer-zagrozenia-90", "block": 3, "blockName": "Ochrona środowiska", "topic": "Materiały zagrażające środowisku", "adrRef": "ADR 5.3.2.3", "why": "Numer rozpoznawczy zagrożenia (górny numer na tablicy pomarańczowej) dla materiałów zagrażających środowisku UN 3077 i UN 3082 to 90. Należy do znaczeń specjalnych."}, {"id": "b3-obowiazek-srodowisko", "block": 3, "blockName": "Ochrona środowiska", "topic": "Obowiązek ochrony środowiska", "adrRef": "ADR 1.4.1 / 7.5.1", "why": "Każdy uczestnik przewozu ma obowiązek podejmować środki zapobiegające szkodzie w środowisku podczas przewozu, załadunku i rozładunku. To ogólna zasada — niezależnie od tego, czy doszło do wycieku."}, {"id": "b3-odpady-dokument", "block": 3, "blockName": "Ochrona środowiska", "topic": "Odpady", "adrRef": "ADR 5.4.1.1.3", "why": "Słowo ODPAD powinno się znaleźć po numerze UN, np. UN 1230 odpad metanol 3 (6.1) II, (D/E)."}, {"id": "b3-odpady-klasyfikacja", "block": 3, "blockName": "Ochrona środowiska", "topic": "Odpady", "adrRef": "ADR 2.1.3 / 5.4.1.1.3", "why": "Odpad podlega ADR, jeśli spełnia kryteria którejś z klas zagrożenia. W dokumencie przed nazwę wpisuje się słowo ODPAD (np. UN 1230 ODPAD METANOL). Za klasyfikację odpowiada nadawca/producent, a NIE kierowca."}, {"id": "b3-odpady-tablica", "block": 3, "blockName": "Ochrona środowiska", "topic": "Odpady", "adrRef": "przepisy krajowe", "why": "Oznakowanie pojazdów przewożących ODPADY w Polsce zawiera tylko jedna tablice ODPADY 30 x 40 cm z przodu pojazdu. NIE jest wymagane przy przewozie odpadów sklasyfikowanych jako ADR. W transporcie międzynarodowym odpadów sklasyfikowanych jako ADR używamy oznakowania ADR i \"A\" z przodu i z tyłu jednostki (Niemcy, Austria, Czechy)."}, {"id": "b3-srodowisko-wyciek", "block": 3, "blockName": "Ochrona środowiska", "topic": "Obowiązek ochrony środowiska", "adrRef": "ADR 1.4.1", "why": "Przy wycieku materiału zagrażającego środowisku kierowca ma, o ile to bezpieczne, ograniczyć skażenie: zatrzymać wyciek u źródła, nie dopuścić do przedostania się substancji do kanalizacji, rowów, cieków wodnych. Nie spłukiwać wodą do studzienek — to roznosi skażenie."}, {"id": "b3-srodowisko-znak-ryba", "block": 3, "blockName": "Ochrona środowiska", "topic": "Obowiązek ochrony środowiska", "adrRef": "ADR 5.2.1.8", "why": "Materiały zagrażające środowisku wodnemu oznacza się znakiem: ryba i drzewo (martwa ryba i uschnięte drzewo) na białym tle. Znak ostrzega, że substancja jest niebezpieczna dla organizmów wodnych i środowiska — wymaga szczególnej ostrożności przy wycieku."}, {"id": "b3-un-srodowisko", "block": 3, "blockName": "Ochrona środowiska", "topic": "Materiały zagrażające środowisku", "adrRef": "ADR 3.2.1", "why": "Materiał zagrażający środowisku: stan stały UN 3077, stan ciekły UN 3082. Należą do klasy 9."}, {"id": "b3-wyciek-sekwencja", "block": 3, "blockName": "Ochrona środowiska", "topic": "Reakcja na wyciek", "adrRef": "ADR 5.4.3.4", "why": "Kolejność przy wycieku (o ile bezpieczne): 1) zatrzymać pojazd w bezpiecznym miejscu i wyłączyć silnik, 2) zabezpieczyć teren i ostrzec innych, 3) ograniczyć wyciek u źródła i nie dopuścić do kanalizacji, 4) powiadomić służby (112) podając dane z tablicy. Życie ludzkie ma pierwszeństwo przed ochroną mienia i środowiska."}, {"id": "b3-wyciek-srodowisko", "block": 3, "blockName": "Ochrona środowiska", "topic": "Reakcja na wyciek", "adrRef": "ADR 5.4.3.4", "why": "Jeżeli jest to właściwe i bezpieczne, zapobiec przedostaniu się uwolnionych materiałów do środowiska wodnego lub kanalizacji oraz zebrać uwolnione materiały, używając wyposażenia przewożonego w jednostce transportowej (osłona otworów kanalizacyjnych, łopata, pojemnik)."}, {"id": "b3-znak-srodowisko", "block": 3, "blockName": "Ochrona środowiska", "topic": "Materiały zagrażające środowisku", "adrRef": "ADR 5.2.1.8.1", "why": "Znak wymagany dla materiałów zagrażających środowisku (ryba i drzewo). Umieszcza się go na opakowaniach większych niż 5 kg lub 5 litrów. Zagrożenie w przypadku przedostania się do środowiska wodnego lub kanalizacji."}, {"id": "b3-znak-temperatura", "block": 3, "blockName": "Ochrona środowiska", "topic": "Materiały zagrażające środowisku", "adrRef": "ADR 5.2.1.8.1", "why": "Znak dla towarów w podwyższonej temperaturze (czerwony trójkąt z termometrem): materiały stałe powyżej 240 st. C, ciekłe powyżej 100 st. C. Zagrożenie poparzeniem. Wskazówka: unikać kontaktu z gorącymi częściami jednostki transportowej i z uwolnionym materiałem."}, {"id": "b4-austria-eskorta", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o tunelu", "adrRef": "wymogi krajowe", "why": "W niektórych krajach wymaga się dodatkowych wymogów, np. w Austrii jednostka transportową powinna być wyposażona w lampę o świetle pomarańczowym. Jednostki, których oznakowanie na tablicy rozpoczyna się od cyfry 2 lub zawierające podwojne cyfry 3, 4, 5, 6, 8 lub poprzedzone litera X wymagaja eskorty podczas przejazdu przez tunele."}, {"id": "b4-certyfikat-pakowania", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 5.4.2", "why": "Certyfikat pakowania kontenera/pojazdu wymagany jest przed załadunkiem, który poprzedza przewóz MORSKI. Może być elementem dokumentu MULTIMODAL DANGEROUS GOODS FORM lub DGN."}, {"id": "b4-cv2-plomien", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o załadunku", "adrRef": "ADR CV2 / 7.5.11", "why": "Przed dokonaniem załadunku powierzchnia ładunkowa pojazdu lub kontenera powinna zostać dokładnie oczyszczona. Zabrania się używania otwartego płomienia wewnątrz pojazdu lub kontenera oraz w ich pobliżu, a także podczas załadunku i rozładunku (przepis szczególny CV2 — 7.5.11)."}, {"id": "b4-cv28-zywnosc", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o załadunku", "adrRef": "ADR 7.5.4 / CV28", "why": "Jeżeli w kolumnie 18 tabeli wskazany jest przepis szczególny CV28, towar należy oddzielić od żywności lub karmy dla zwierząt: (a) ciągłymi przegrodami o wysokości nie mniejszej niż sztuki przesyłek oznaczone nalepkami 6.1, 6.2, 9; (b) sztukami przesyłek, które NIE są zaopatrzone w nalepki 6.1, 6.2, 9; (c) wolna przestrzenią o szerokości nie mniej niż 0,8 m lub przez całkowite przykrycie (plandeka, pokrywa z tektury). Dotyczy UN 2212, 2315, 2590, 3151, 3152, 3245."}, {"id": "b4-cv3-cv15", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o załadunku", "adrRef": "ADR CV3 / CV15", "why": "Przepisy dotyczące manipulowania i układania wprowadzają ograniczenie masy ładunku na jednostkę transportową (na \"otwartych tablicach\"). Dotyczy towarów klasy 1, 4.1, 5.2 (samoreaktywne, nadtlenki organiczne typu B, C, D, E, F), które mają właściwości wybuchowe. Ograniczenia zawarte w przepisach CV3 i CV15."}, {"id": "b4-cysterna-wielokomorowa", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Oznakowanie pojazdu w praktyce", "adrRef": "ADR 5.3.2.1.3", "why": "Dla numerów UN 1202, UN 1203, UN 1223, UN 1268, UN 1863 można oznakować cysternę wielokomorowa tak, jakby wiozła jeden produkt — najniebezpieczniejszy z przewożonych."}, {"id": "b4-dokument-jezyk", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 5.4.1.4.1", "why": "Dokument przewozowy sporządza się w języku kraju nadania, a w transporcie międzynarodowym również w języku angielskim lub niemieckim lub francuskim. Dokument przewozowy należy przechowywać 3 miesiące."}, {"id": "b4-dokument-kto", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 5.4.1", "why": "Za dokument przewozowy odpowiedzialny jest NADAWCA. Dokument powinien być sporządzony w języku kraju nadania, a w transporcie międzynarodowym również w języku angielskim lub niemieckim lub francuskim. Nie musi być sporządzony pismem maszynowym ani wydrukowany."}, {"id": "b4-dokument-zapisy", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 5.4.1.1", "why": "Zapisy specjalne w dokumencie: \"Przewóz zgodny z 1.1.4.2.1\" — przewóz multimodalny; \"ODPAD\" po numerze UN; \"próżny DPPL, 8\" — próżne opakowania z numerem nalepki; \"GORĄCY\" gdy nazwa nie zawiera PODWYŻSZONA TEMPERATURA lub STOPIONY; \"ZAGRAŻAJĄCY ŚRODOWISKU\" gdy spełnia kryteria (nie stosuje się do UN 3077 i UN 3082)."}, {"id": "b4-dokument-zawartosc", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 5.4.1.1.1", "why": "Kolejność zapisu w dokumencie przewozowym: numer UN, prawidłowa nazwa przewozowa, numery nalepek, grupa pakowania (GP), kod tunelu. Przykład: UN 1203 Benzyna Silnikowa zagrażający środowisku, 3, II, (D/E)."}, {"id": "b4-duze-ryzyko-cel", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Towary dużego ryzyka", "adrRef": "ADR 1.10", "why": "Ochrona towarów ma na celu zminimalizowanie ryzyka kradzieży oraz użycia ich niezgodnie z przeznaczeniem. W szczególności zapobieżenie kradzieży pojazdów, kradzieży towarów, zamachom na zaparkowane pojazdy."}, {"id": "b4-duze-ryzyko-progi", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Towary dużego ryzyka", "adrRef": "ADR 1.10.3.1", "why": "Progi towarów dużego ryzyka: klasa 1 (1.1, 1.2, 1.3) — każda ilość w sztukach; gazy palne nietrujące (F, FC) — cysterna 3000 l; gazy trujące (T, TF, TC, TO, TFC, TOC) — każda ilość; klasa 3 GP I i II — cysterna 3000 l; klasa 6.1 GP I — każda ilość; klasa 8 GP I — cysterna 3000 l."}, {"id": "b4-gasnice-liczba", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór gaśnic", "adrRef": "ADR 8.1.4", "why": "Minimalna liczba gaśnic na jednostce transportowej wynosi 2 — niezależnie od dopuszczalnej masy całkowitej. Jedna gaśnica 12 kg NIE wystarczy: zawsze muszą być co najmniej dwie."}, {"id": "b4-gasnice-pojemnosc", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór gaśnic", "adrRef": "ADR 8.1.4", "why": "Minimalna całkowita pojemność gaśnic wg dopuszczalnej masy całkowitej jednostki transportowej: do 3,5 t = 4 kg; powyżej 3,5 do 7,5 t = 8 kg; powyżej 7,5 t = 12 kg. Gaśnice muszą być typu ABC."}, {"id": "b4-gasnice-rozklad", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór gaśnic", "adrRef": "ADR 8.1.4.1", "why": "Rozkład gaśnic: co najmniej jedna gaśnica do gaszenia pożaru silnika lub kabiny o minimalnej pojemności 2 kg (dla każdej kategorii masy). Wymagana gaśnica dodatkowa: min. 2 kg dla jednostki do 3,5 t; min. 6 kg dla jednostki powyżej 3,5 t."}, {"id": "b4-gasnice-s3", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór gaśnic", "adrRef": "ADR przepis S3", "why": "Zgodnie z przepisem S3 dla towarów klasy 6.2 (zakaźne) niezależnie od DMC pojazdu wystarczy gaśnica 2 kg typu ABC, a latarka może być o dowolnej konstrukcji."}, {"id": "b4-instrukcje-forma", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 5.4.3", "why": "Instrukcje pisemne zawierają: sprzet ochrony ogólnej i indywidualnej, czynności w razie wypadku lub awarii, charakterystyke zagrożeń, wzory nalepek. Muszą być dostępne w języku zrozumiałym dla załogi, przechowywane w kabinie kierowcy w łatwo dostepnym miejscu, wydrukowane W KOLORZE. Po zakończeniu transportu powinny pozostać w pojeździe. Wymagane tylko na \"otwartych tablicach\"."}, {"id": "b4-instrukcje-kto", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 5.4.3", "why": "Za instrukcje pisemne odpowiedzialny jest PRZEWOŹNIK. Instrukcje są zgodne ze wzorem zawartym w umowie ADR i uniwersalne — dla każdego produktu takie same. Należy się z nimi zapoznać przed rozpoczęciem transportu."}, {"id": "b4-kontener-cysterna", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Oznakowanie pojazdu w praktyce", "adrRef": "ADR 5.3.1.3", "why": "Kontener-cysterna powinien być oznakowany nalepkami ostrzegawczymi z 4 stron."}, {"id": "b4-kontrola", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Towary dużego ryzyka", "adrRef": "art. 99 ustawy", "why": "Kontrola przewozu zgodnie z art. 99 ustawy o transporcie towarów niebezpiecznych może być przeprowadzana na drogach i parkingach przez: inspektorów Inspekcji Transportu Drogowego, funkcjonariuszy Policji, Straży Granicznej, Służb Celnych oraz żołnierzy Żandarmerii Wojskowej (w zakresie przewozu wykonywanego przez siły zbrojne)."}, {"id": "b4-ladunek-calkowity", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o załadunku", "adrRef": "ADR 1.2.1", "why": "Ładunek całkowity oznacza ładunek pochodzący od jednego nadawcy, mającego wyłączne prawo do używania pojazdu lub kontenera wielkiego, a wszystkie czynności załadunkowe i rozładunkowe wykonywane są zgodnie z instrukcjami nadawcy lub odbiorcy. W odniesieniu do materiałów promieniotwórczych odpowiednim określeniem jest \"używanie wyłączne\"."}, {"id": "b4-lopata-oslona", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór wyposażenia", "adrRef": "ADR 8.1.5.3", "why": "Łopata, osłona otworów kanalizacyjnych i pojemnik do zbierania pozostałości są wymagane TYLKO dla nalepek 3, 4.1, 4.3, 8 lub 9. Niezależnie od ilości członków załogi — tylko 1 sztuka w pojeździe."}, {"id": "b4-maska-ucieczkowa", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór wyposażenia", "adrRef": "ADR 8.1.5.3", "why": "Maska ucieczkowa dla KAŻDEGO członka załogi pojazdu powinna być przewożona w jednostce transportowej w przypadku nalepek ostrzegawczych 2.3 lub 6.1."}, {"id": "b4-nadzor-parkingi", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Ruch drogowy i postoj", "adrRef": "ADR 8.4 / S1(6), S14-S24", "why": "Pojazdy przewożące towary niebezpieczne w ilościach podanych w przepisach specjalnych S1(6) i S14 do S24 powinny być nadzorowane lub mogą być zaparkowane bez nadzoru na parkingach strzeżonych lub strzeżonych miejscach na terenie przedsiębiorstwa. W razie braku takich warunków: (a) parking nadzorowany przez personel poinformowany o właściwościach ładunku i miejscu pobytu kierowcy; (b) parking gdzie pojazd nie jest narażony na uszkodzenie; (c) miejsce na otwartym terenie, oddzielone od głównych dróg i budynków mieszkalnych."}, {"id": "b4-oznakowanie-luzem-cysterna", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Oznakowanie pojazdu w praktyce", "adrRef": "ADR 5.3.1 / 5.3.2", "why": "Jednostki przewożące towary LUZEM lub W CYSTERNIE powinny być oznakowane tablicami Z NUMERAMI z przodu i tyłu jednostki transportowej oraz nalepkami z TRZECH stron — z obu boków oraz z tyłu."}, {"id": "b4-oznakowanie-sztuki-pojazd", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Oznakowanie pojazdu w praktyce", "adrRef": "ADR 5.3.2", "why": "Jednostki przewożące towary niebezpieczne w SZTUKACH PRZESYŁKI (np. butle gazowe, DPPL, kanistry, BIG-BAGi) powinny być oznakowane WYŁĄCZNIE tablicami BEZ numerów z przodu i tyłu pojazdu. NIE stosujemy w takim przypadku nalepek."}, {"id": "b4-oznakowanie-wariant2", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Oznakowanie pojazdu w praktyce", "adrRef": "ADR 5.3.2.1.2", "why": "Drugi sposób oznakowania jednostki przewożącej jeden ładunek luzem lub w cysternie: tablice BEZ numerów z przodu i tyłu pojazdu oraz tablice Z NUMERAMI na obu bokach. Nalepki ostrzegawcze muszą być umieszczone z obu boków i z tyłu pojazdu."}, {"id": "b4-pasazerowie", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Ruch drogowy i postoj", "adrRef": "ADR 8.3.1", "why": "W pojeździe \"na pełnym ADR\" nie wolno przewozić pasażerów, a jedynie członków załogi. Każdy członek załogi musi mieć dokument tożsamości."}, {"id": "b4-plan-ochrony-wymogi", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Towary dużego ryzyka", "adrRef": "ADR 1.10", "why": "Zapamiętaj: plan ochrony WYMAGA legitymowania kierowcy i wykazu osób. NIE WYMAGA specjalnego znakowania przesyłek lub pojazdów, nadzoru GPS ani konwojenta."}, {"id": "b4-plan-ochrony", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Towary dużego ryzyka", "adrRef": "ADR 1.10.3.2", "why": "Plan ochrony zawiera m.in.: szczegółowy podział obowiązków i wykaz osób, wykaz towarów niebezpiecznych podlegających ochronie, opis czynności i ocenę zagrożeń, plan szkolenia i procedury postępowania, procedury powiadamiania, procedury oceny i testowania planów, działania zapewniające ochronę fizyczna informacji, działania ograniczające dostęp do informacji."}, {"id": "b4-plyn-do-oczu", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór wyposażenia", "adrRef": "ADR 8.1.5.2", "why": "Płyn do płukania oczu NIE jest wymagany przy nalepkach 1, 1.4, 1.5, 1.6, 2.1, 2.2 i 2.3. Płyn to tylko 1 sztuka w pojeździe, niezależnie od ilości członków załogi."}, {"id": "b4-predkosc", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Ruch drogowy i postoj", "adrRef": "przepisy krajowe", "why": "Dla przewozu towarów niebezpiecznych NIE obowiązuje podwyższenie prędkości w terenie zabudowanym. Maksymalnie 50 km/h."}, {"id": "b4-segregacja-zakazy", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o załadunku", "adrRef": "ADR 7.5.2.1", "why": "Zakazy ładowania razem do jednego pojazdu lub kontenera zawarte są w przepisie 7.5.2.1. W uproszczeniu dotyczą towarów klasy 1 (wybuchowe), 4.1 + 1 (samoreaktywne) oraz 5.2 + 1 (nadtlenki organiczne) o właściwościach wybuchowych."}, {"id": "b4-sprawozdanie-roczne", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 1.8.3.6", "why": "Każda firma ładująca, przewożąca, rozładowująca towary niebezpieczne musi wyznaczyć doradcę DGSA. Sporządza on sprawozdanie roczne do ITD, składane do 28 lutego za poprzedni rok. Za niezłożenie sprawozdania kara wynosi 5000 PLN."}, {"id": "b4-swiadectwo-typy", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 9.1.1.2", "why": "Oznaczenia pojazdów wymagających świadectwa: EX/II i EX/III — przewóz klasy 1 (wybuchowe); FL i AT — cysterny; MEMU — mobilna jednostka do wytwarzania materiałów wybuchowych."}, {"id": "b4-swiadectwo", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 9.1.3", "why": "Świadectwo dopuszczenia (tzw. \"czerwony pasek\") wymagane jest przy przewozie towarów klasy 1 (pojazdy EX/II, EX/III) oraz w cysternach (pojazdy FL, AT) i MEMU. Potwierdza specjalna konstrukcje pojazdu. Wydawany w Polsce przez TDT na maksymalny okres JEDNEGO ROKU. Pojazdy przewożące sztuki przesyłki (poza wybuchowymi) i luzem NIE muszą mieć świadectwa — np. butle z gazem, DPPL, kanistry."}, {"id": "b4-tunel-brak-kodu", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o tunelu", "adrRef": "ADR 1.9.5 / kol. 15", "why": "Do tunelu kategorii E mogą wjeżdżać pojazdy z towarami, które w kolumnie 15 tabeli A mają \"(-)\" — czyli brak kodu tunelowego. Należą tu m.in. UN 2814, 2900, 2919, 3166, 3171, 3331, 3359, 3373, 3549."}, {"id": "b4-tunel-zachowanie", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o tunelu", "adrRef": "ADR 8.6 / przepisy ruchu", "why": "W tunelu ZAKAZUJE się: palenia, używania okularów przeciwsłonecznych, używania telefonu komórkowego i radia CB. W tunelu NALEŻY: stosować się do znaków i sygnałów, słuchać komunikatów radiowych, włączyć światła mijania."}, {"id": "b4-tunele-kategorie", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o tunelu", "adrRef": "ADR 1.9.5", "why": "Kategorie tuneli: A — bez ograniczeń (znak D-37, nieoznakowany), B, C, D, E — coraz bardziej restrykcyjne. Kod (B) = zagrażające wybuchem o bardzo dużym zasięgu; (C) = wybuch o dużym zasięgu lub działanie trujące o dużym zasięgu; (D) = jw. lub duży pożar; (E) = zakaz dla ilości ograniczonych powyżej 8 t brutto."}, {"id": "b4-tunele-kod", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o tunelu", "adrRef": "ADR 1.9.5 / kol. 15", "why": "Kategoria tunelu podaje informacje, która umożliwia przewoźnikowi (kierowcy) precyzyjne określenie kategorii tunelu, przez które NIE jest dozwolony przewóz konkretnego towaru. Podana jest pod znakiem B-13a w postaci litery B, C, D lub E."}, {"id": "b4-wyposazenie-jednostka", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór wyposażenia", "adrRef": "ADR 8.1.5", "why": "Wyposażenie na jednostkę transportową: klin pod koła dla KAŻDEGO pojazdu (o rozmiarze odpowiednim do DMC i średnicy kol), dwa stojące znaki ostrzegawcze, płyn do płukania oczu."}, {"id": "b4-wyposazenie-zaloga", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór wyposażenia", "adrRef": "ADR 8.1.5.2", "why": "Dla KAŻDEGO członka załogi pojazdu: kamizelka ostrzegawcza, przenosne urządzenie oświetleniowe (latarka), para rękawic ochronnych, ochrona oczu (okulary)."}, {"id": "b4-znak-b13", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Ruch drogowy i postoj", "adrRef": "znaki drogowe PL", "why": "Znak B-13 oznacza zakaz wjazdu dla pojazdów przewożących towary niebezpieczne klas: 1, gazy palne (2F), 3, 4.1, 4.2, 4.3, 5.1, 5.2 — czyli wszystkie nalepki z płomieniem."}, {"id": "b4-znak-b13a", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Ruch drogowy i postoj", "adrRef": "znaki drogowe PL", "why": "Znak B-13a / C-3h oznacza zakaz wjazdu dla pojazdów przewożących towary niebezpieczne WSZYSTKICH KLAS oznakowanych tablicami pomarańczowymi."}, {"id": "b4-znak-b14", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Ruch drogowy i postoj", "adrRef": "znaki drogowe PL", "why": "Znak B-14 oznacza zakaz wjazdu ze szkodliwymi dla środowiska wodnego: gazy trujące, żrące, klasa 3, 4.3, 6.1, 6.2, 8, część klasy 9 + znak \"ryba\" (zagrażający środowisku)."}, {"id": "b4-znaki-pozostale", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Ruch drogowy i postoj", "adrRef": "znaki drogowe PL", "why": "D-37 — dozwolony wjazd z wszystkimi towarami niebezpiecznymi (tunel). C-17 — nakazany kierunek jazdy dla pojazdów przewożących towary niebezpieczne. T-23i, T-23j, T-23h — tabliczki precyzujące rodzaj towaru."}, {"id": "b5-dgsa-zdarzenie", "block": 5, "blockName": "Po wypadku", "topic": "Powiadamianie służb", "adrRef": "ADR 1.8.5", "why": "O każdym zdarzeniu należy poinformować doradcę DGSA w firmie w celu oceny, czy nie jest wymagane sporządzenie raportu powypadkowego."}, {"id": "b5-dokument-awaryjny", "block": 5, "blockName": "Po wypadku", "topic": "Powiadamianie służb", "adrRef": "ADR 5.4.1", "why": "Najważniejszym dokumentem w sytuacji awaryjnej jest DOKUMENT PRZEWOZOWY, ponieważ zawiera informacje na temat towaru i jego właściwości."}, {"id": "b5-fissile", "block": 5, "blockName": "Po wypadku", "topic": "Wskazówki per klasa", "adrRef": "ADR 5.4.3.4 tabela", "why": "Nalepka 7E (FISSILE — materiał rozszczepialny) oznacza zagrożenie reakcja łańcuchowa."}, {"id": "b5-gasnica-parametry", "block": 5, "blockName": "Po wypadku", "topic": "Gaszenie pożaru", "adrRef": "praktyka gaszenia", "why": "Strumień proszku kierujemy w źródło płomieni od strony nawietrznej. Czas wyładowania gaśnicy 6 kg to około 10 s, a 2 kg to około 6 s. Zasięg gaśnic to około 4 m."}, {"id": "b5-gaszenie", "block": 5, "blockName": "Po wypadku", "topic": "Gaszenie pożaru", "adrRef": "ADR 5.4.3.4", "why": "Jeżeli jest to właściwe i bezpieczne, użyć gaśnic w celu ugaszenia małego lub będącego w fazie początkowej pożaru, obejmującego opony, hamulce lub przedział silnika. Członkowie załogi NIE powinni gasić pożaru obejmującego przedział ładunkowy. Nie gasimy ładunku."}, {"id": "b5-kolejnosc-informacji", "block": 5, "blockName": "Po wypadku", "topic": "Powiadamianie służb", "adrRef": "procedury krajowe", "why": "Kolejność przekazywanych informacji: miejsce zdarzenia, rodzaj zdarzenia (wypadek, kolizja, wyciek), skutki zdarzenia, liczba ofiar, rozmiar zdarzenia (ile pojazdów, osób), numery UN przewożonego towaru, sposób jego przewozu (luzem, cysterna), ilość towaru niebezpiecznego, czy nastąpiło jego uwolnienie."}, {"id": "b5-kolejnosc", "block": 5, "blockName": "Po wypadku", "topic": "Reakcja po wypadku", "adrRef": "ADR 5.4.3.4", "why": "Czynności wg instrukcji pisemnej: zahamować pojazd, wyłączyć silnik i odłączyć akumulator wyłącznikiem głównym; unikać źródeł zapłonu (nie palić, nie używać e-papierosów, nie włączać urządzeń elektrycznych); powiadomić służby ratownicze; założyć kamizelkę i ustawić stojące znaki ostrzegawcze; zapewnić ratownikom dostęp do dokumentów; nie wchodzić na uwolnione materiały, pozostawać po stronie nawietrznej."}, {"id": "b5-mocowanie-kontrola", "block": 5, "blockName": "Po wypadku", "topic": "Mocowanie ładunku", "adrRef": "ADR 7.5.7", "why": "Kierowca odpowiada za sprawdzenie zamocowania ładunku przed jazdą i po każdej przerwie, na której mogło dojść do przemieszczenia. Luźny pas, uszkodzona burta lub przesunięta paleta to podstawa do przerwania jazdy i poprawy mocowania."}, {"id": "b5-mocowanie-sila", "block": 5, "blockName": "Po wypadku", "topic": "Mocowanie ładunku", "adrRef": "ADR 7.5.7.1", "why": "Ładunek musi być zamocowany tak, by przy gwałtownym hamowaniu nie przesunął się i nie zagroził stabilności pojazdu. Siły w transporcie: do przodu ok. 0,8 masy ładunku (hamowanie), do tyłu i na boki ok. 0,5 masy. Dlatego mocowanie z przodu musi być najmocniejsze."}, {"id": "b5-mocowanie", "block": 5, "blockName": "Po wypadku", "topic": "Mocowanie ładunku", "adrRef": "ADR 7.5.7", "why": "Do mocowania ładunku używamy atestowanych pasów, burt przesuwanych, przegród nastawnych, mat antypoślizgowych, konstrukcji pojazdu (punkty kotwiczenia) lub wypełnienia pustych przestrzeni. Siła działająca na ładunek zmniejsza się wraz ze wzrostem promienia zakrętu. Ładunek ciekły w przypadku piętrowania należy umieszczać jak najniżej. Ładunek można piętrować tylko jeśli konstrukcja opakowania na to pozwala. Kąt pasa maksymalnie 45 stopni."}, {"id": "b5-numery-alarmowe", "block": 5, "blockName": "Po wypadku", "topic": "Powiadamianie służb", "adrRef": "procedury krajowe", "why": "Powiadamianie na numer 112 lub 999, 998 lub 997. Należy przekazać wszystkie dostępne informacje."}, {"id": "b5-oznakowanie-miejsca", "block": 5, "blockName": "Po wypadku", "topic": "Reakcja po wypadku", "adrRef": "ADR 8.1.5 / 5.4.3.4", "why": "Założyć kamizelkę ostrzegawcza i odpowiednio umieścić stojące znaki ostrzegawcze (dwa). Zapewnić przybylym ratownikom łatwy dostęp do dokumentów przewozowych."}, {"id": "b5-pierwsza-pomoc-kontakt", "block": 5, "blockName": "Po wypadku", "topic": "Pierwsza pomoc", "adrRef": "ADR 5.4.3 (instrukcje pisemne)", "why": "Przy kontakcie substancji ze skórą lub oczami: natychmiast płukać miejsce duża ilością letniej wody przez co najmniej 15-20 minut, zdejmując skażoną odzież. NIE stosować środków neutralizujących. DO WERYFIKACJI: treść medyczna, przegląd ratownik/instruktor."}, {"id": "b5-pierwsza-pomoc-numer", "block": 5, "blockName": "Po wypadku", "topic": "Pierwsza pomoc", "adrRef": "ADR 5.4.3", "why": "Numer alarmowy w całej Unii Europejskiej to 112. Zgłaszając wypadek z towarem niebezpiecznym, podaj: miejsce, numer UN i nalepki z tablicy, rodzaj zdarzenia, liczbę poszkodowanych. Instrukcje pisemne (te w kabinie) opisują pierwsze czynności dla każdej klasy zagrożenia."}, {"id": "b5-pierwsza-pomoc-wdychanie", "block": 5, "blockName": "Po wypadku", "topic": "Pierwsza pomoc", "adrRef": "ADR 5.4.3 (instrukcje pisemne)", "why": "Przy wdychaniu par lub gazów: wyprowadzić poszkodowanego na świeże powietrze, na strefę nawietrzną (wiatr od pleców), zapewnić spokój i ciepło, wezwać pomoc. Nie wolno samemu wchodzić w strefę skażoną bez ochrony — ryzyko, że ratownik też straci przytomność. DO WERYFIKACJI: treść medyczna."}, {"id": "b5-pierwsza-pomoc", "block": 5, "blockName": "Po wypadku", "topic": "Reakcja po wypadku", "adrRef": "ADR 5.4.3.4", "why": "Zdjąć zanieczyszczone ubranie i użyte zanieczyszczone wyposażenie ochronne oraz usunąć je w sposób bezpieczny. Unikać wdychania oparów, dymu, pyłu i pary poprzez pozostawanie po stronie nawietrznej. Nie wchodzić na uwolnione materiały i nie dotykać ich."}, {"id": "b5-wiele-zagrozen", "block": 5, "blockName": "Po wypadku", "topic": "Wskazówki per klasa", "adrRef": "ADR 5.4.3.4 uwaga 1", "why": "UWAGA 1 z instrukcji pisemnej: w przypadku towarów niebezpiecznych stwarzających więcej niż jedno zagrożenie oraz ładunków mieszanych, stosuje się KAŻDA z określonych dla nich wskazówek."}, {"id": "b5-wskazowki-klasy", "block": 5, "blockName": "Po wypadku", "topic": "Wskazówki per klasa", "adrRef": "ADR 5.4.3.4 tabela", "why": "Wskazówki dodatkowe z instrukcji pisemnej: klasa 1 — schronić się i pozostać z dala od okien; 2.1/2.2/2.3 — schronić się, unikać zagłębień terenu; 5.1/5.2 — nie dopuszczać do zmieszania z materiałami zapalnymi lub palnymi (np. trocinami); 6.1 — użyć maski ucieczkowej; 7 — ograniczyć czas narażenia; 4.3 — uwolniony materiał utrzymywać w stanie suchym, pod przykryciem."}, {"id": "b5-zajecia-praktyczne-info", "block": 5, "blockName": "Po wypadku", "topic": "Reakcja po wypadku", "adrRef": "program kursu (Dz.U. 2021 poz. 2150)", "why": "INFO: zajęcia praktyczne z pierwszej pomocy i gaszenia pożaru są obowiązkowa częścią kursu stacjonarnego ADR. Trening w aplikacji utrwala wiedzę, realny skill ćwiczy się na kursie z instruktorem."}, {"id": "b5-zrodla-zaplonu", "block": 5, "blockName": "Po wypadku", "topic": "Reakcja po wypadku", "adrRef": "ADR 5.4.3.4", "why": "Unikać źródeł zapłonu, w szczególności nie palić, nie używać papierosów elektronicznych lub podobnych urządzeń oraz nie włączać żadnych urządzeń elektrycznych."}, {"id": "s-1132-oblicz-energia", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 1.1.3.2", "why": "Limit 54 000 MJ to nie liczba do wykucia — to wynik mnożenia. Wartość energetyczna = litry paliwa razy wartość energetyczna tego paliwa (kol. z uwagi 1: olej napędowy 36 MJ/l, benzyna 32 MJ/l, LPG 24 MJ/l). Przykład graniczny: 1500 l oleju napędowego x 36 MJ/l = 54 000 MJ — dokładnie na limicie. Żeby sprawdzić, czy przewóz gazu/paliwa w zbiornikach przewożonych pojazdów mieści się w wyłączeniu dla gazów, liczysz iloczyn i porównujesz z 54 000 MJ."}, {"id": "s-1136-co-zostaje", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6", "why": "Wyłączenie 1.1.3.6 nie zwalnia ze wszystkiego. ZOSTAJE: certyfikowane i oznakowane opakowania, gaśnica 2 kg ABC z data przeglądu, dokument przewozowy, szkolenie stanowiskowe. ODPADA: tablice pomarańczowe, zaświadczenie ADR, instrukcja pisemną, skrzynka ADR, znaki drogowe ADR, DGSA, zakaz pasażerów."}, {"id": "s-1136-gdzie-kategoria", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR kol. 15 Tabeli A", "why": "Żeby policzyć punkty, najpierw musisz znać kategorię transportową towaru. Sprawdzasz ją w tabeli A, w kolumnie 15 (ta sama kolumna zawiera kod tunelowy w nawiasie)."}, {"id": "s-1136-kat0-blokada", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6.3", "why": "Kategoria 0 ma limit 0 — każda ilość oznacza pełny ADR. Nie ma znaczenia, ze suma punktów z pozostałych towarów jest niska. Kategoria 0 blokuje wyłączenie całkowicie."}, {"id": "s-1136-kat1-wyjatek-oblicz", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6.3", "why": "UN 1017 (chlor) należy do wyjątku kategorii 1: limit 50 kg, mnożnik x20 zamiast x50. 20 kg x 20 = 400 punktów."}, {"id": "s-1136-kat4-zero", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6.3", "why": "Kategoria 4 ma mnożnik 0 — nie dolicza się do sumy niezależnie od ilości. 500 kg kąt. 4 = 0 punktów. Liczy się tylko 100 l kąt. 3 = 100 punktów."}, {"id": "s-1136-mnozniki-tabela", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6.4", "why": "Podstawa liczenia punktów: ilość x mnożnik kategorii. Kąt. 1 = x50, kąt. 2 = x3, kąt. 3 = x1, kąt. 4 = x0. Suma nie może przekroczyć 1000."}, {"id": "s-1136-oblicz-1", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6", "why": "Kategoria 2 ma mnożnik x3. 100 l x 3 = 300 punktów. Wynik poniżej 1000 — wyłączenie przysługuje."}, {"id": "s-1136-oblicz-2", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6", "why": "Sumujemy iloczyny: 50 l kąt. 2 = 50 x 3 = 150. 200 kg kąt. 3 = 200 x 1 = 200. Razem 350 punktów. Wyłączenie przysługuje."}, {"id": "s-1136-oblicz-3", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyliczenie 1000 punktów", "adrRef": "ADR 1.1.3.6", "why": "300 l kąt. 2 = 300 x 3 = 900 punktów. Dołożenie 200 kg kąt. 3 (x1 = 200) daje 1100 — przekroczenie 1000. Wyłączenie nie przysługuje, jedziesz na pełnym ADR."}, {"id": "s-2025-baterie-sodowe", "block": 2, "blockName": "Główne zagrożenia", "topic": "Zmiany ADR 2025", "adrRef": "ADR 2025 UN 3551/3552", "why": "ZMIANA ADR 2025: wprowadzono baterie sodowo-jonowe — UN 3551 (z elektrolitem organicznym) i UN 3552 (zapakowane z urządzeniem lub w urządzeniu). Kod klasyfikacyjny M4 obejmuje teraz baterie litowe i sodowo-jonowe. Kompendium ADR 2023 tego nie zawiera."}, {"id": "s-2025-dokument-kabina", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Zmiany ADR 2025", "adrRef": "ADR 5.4.1 (2025)", "why": "ZMIANA ADR 2025: od 1 lipca 2025 dokumenty przewozowe muszą znajdować się w kabinie kierowcy. Wcześniej dopuszczalne było inne umiejscowienie. Kompendium ADR 2023 tego nie zawiera."}, {"id": "s-2025-lq-szkolenie", "block": 1, "blockName": "Wymagania ogólne", "topic": "Zmiany ADR 2025", "adrRef": "ADR 8.2.3 (2025)", "why": "ZMIANA ADR 2025: doprecyzowano wymóg szkolenia załogi przewożącej towary w ilościach ograniczonych (LQ). Mimo złagodzenia przepisów dla LQ, szkolenie stanowiskowe pozostaje wymagane i powinno być udokumentowane. Kompendium ADR 2023 tego nie precyzuje."}, {"id": "s-2025-pojazdy-baterie", "block": 2, "blockName": "Główne zagrożenia", "topic": "Zmiany ADR 2025", "adrRef": "ADR 2025 UN 3556-3558", "why": "ZMIANA ADR 2025: wprowadzono osobne numery dla pojazdów napędzanych bateriami — UN 3556 (litowo-jonowa), UN 3557 (litowo-metalowa), UN 3558 (sodowo-jonowa). Stosuje się nową instrukcję pakowania P912. Kompendium ADR 2023 tego nie zawiera."}, {"id": "s-butle-po-gazach", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 1.1.3.6.3", "why": "Wszystkie butle po gazach należą do kategorii transportowej 4 — mnożnik 0, bez ograniczeń ilościowych. Może je przewozić kierowca bez zaświadczenia ADR. Uwaga: butle pozostają oznakowane jak w stanie ładownym."}, {"id": "s-co-nie-podlega-adr", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 3.3 SP 188", "why": "Nie podlegają ADR: akumulatory i ogniwa litowe zawarte w urządzeniach wg przepisu 188, pojazdy poddane fumigacji, czynniki chłodzące jak UN 1845 suchy lód. Uwaga: mimo ze nie podlegają ADR, nadal stwarzają zagrożenie — fumigacja i suchy lód grozą uduszeniem."}, {"id": "s-cv28-zywnosc-decyzja", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o załadunku", "adrRef": "ADR 7.5.4 / CV28", "why": "Gdy w kolumnie 18 tabeli A jest przepis CV28, towar trzeba oddzielić od żywności i karmy. Sposoby: ciągle przegrody, sztuki bez nalepek 6.1/6.2/9 jako bufor, wolna przestrzeń min. 0,8 m, albo całkowite przykrycie (plandeka, pokrywa)."}, {"id": "s-cysterna-wielokomorowa-decyzja", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Oznakowanie pojazdu w praktyce", "adrRef": "ADR 5.3.2.1.3", "why": "Dla UN 1202, 1203, 1223, 1268 i 1863 można oznakować cysternę wielokomorowa tak, jakby wiozła jeden produkt — ten najniebezpieczniejszy z przewożonych. Benzyna (UN 1203, numer 33) jest niebezpieczniejsza niż olej napędowy (UN 1202, numer 30)."}, {"id": "s-data-opakowania", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt opakowania", "adrRef": "ADR 4.1.1.15", "why": "Data produkcji na opakowaniu zapisana jest jako miesiąc i rok, np. 07 21 = lipiec 2021. Opakowanie można używać 5 lat od daty produkcji, czyli do lipca 2026. Po 2,5 roku (styczen 2024) powinno być przeprowadzone badanie."}, {"id": "s-dgsa-czy-potrzebny", "block": 1, "blockName": "Wymagania ogólne", "topic": "Podstawy prawne", "adrRef": "ADR 1.8.3", "why": "Doradcę DGSA powinna wyznaczyć KAŻDA firma pakująca, ładująca, transportująca lub rozładowująca towary niebezpieczne — nie tylko przewoźnicy. Kara za niewyznaczenie: 5000 PLN. DGSA sprawdza szkolenia, sporządza sprawozdanie roczne i raport powypadkowy."}, {"id": "s-dokument-1136-punkty", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 5.4.1.1.10", "why": "Przy zastosowaniu zwolnienia 1.1.3.6 należy w dokumencie umieścić zapis o całkowitej ilości towaru dla kategorii transportowej oraz o \"punktach\" (wartości obliczonej), np. kategoria transportową 2 — 100 l — 300 punktów."}, {"id": "s-dokument-odczyt", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 5.4.1", "why": "Nawet nie znając języka dokumentu, kierowca odczyta właściwości towaru po numerze nalepki i grupie pakowania. UN 1580 CHLOROPIKRYNA 6.1 GP I: 6.1 = trujący, GP I = silnie (największe zagrożenie)."}, {"id": "s-dokument-odpad-zapis", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 5.4.1.1.3", "why": "Słowo ODPAD umieszcza się PO numerze UN, przed nazwa: UN 1230 odpad metanol 3 (6.1) II, (D/E)."}, {"id": "s-dokument-prozny", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 5.4.1.1.6", "why": "Zapis dla próżnych opakowań powinien zawierać nazwę opakowania oraz numery nalepek znajdujących się na opakowaniu, np. \"próżny DPPL, 8\"."}, {"id": "s-gasic-czy-nie", "block": 5, "blockName": "Po wypadku", "topic": "Reakcja po wypadku", "adrRef": "ADR 5.4.3.4", "why": "Kierowca gasi TYLKO mały lub początkowy pożar obejmujący opony, hamulce lub przedział silnika — i tylko jeśli to bezpieczne. Pożaru przedziału ładunkowego NIE gasi. Nie gasimy ładunku."}, {"id": "s-gasnica-technika", "block": 5, "blockName": "Po wypadku", "topic": "Reakcja po wypadku", "adrRef": "praktyka gaszenia", "why": "Strumień proszku kierujemy w źródło płomieni, stojąc od strony nawietrznej. Gaśnica 6 kg wystarcza na ok. 10 sekund, 2 kg na ok. 6 sekund. Zasięg około 4 m. Masz jedna próbę — celuj w źródło, nie w płomień."}, {"id": "s-gasnice-1136", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór gaśnic", "adrRef": "ADR 1.1.3.6 / 8.1.4", "why": "Pojazd na wyłączeniu 1.1.3.6 musi mieć 1 gaśnice 2 kg typu ABC. Wyłączenie zwalnia z pełnego wyposażenia, ale NIE z gaśnicy."}, {"id": "s-gasnice-3t", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór gaśnic", "adrRef": "ADR 8.1.4", "why": "Bus 3 t = do 3,5 t. Wymagane: 2 gaśnice, łączna pojemność 4 kg — czyli 2 kg do silnika/kabiny + 2 kg dodatkowa."}, {"id": "s-gasnice-40t", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór gaśnic", "adrRef": "ADR 8.1.4", "why": "Zestaw 40 t = powyżej 7,5 t. Wymagane: minimum 2 gaśnice, łączna pojemność 12 kg, w tym co najmniej jedna 2 kg do silnika/kabiny i co najmniej jedna dodatkowa 6 kg. Typ ABC."}, {"id": "s-gasnice-s3-6-2", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór gaśnic", "adrRef": "ADR przepis S3", "why": "Przepis S3: dla klasy 6.2 (zakaźne) niezależnie od DMC pojazdu wystarczy gaśnica 2 kg typu ABC, a latarka może być dowolnej konstrukcji. To wyjątek od tabeli mas."}, {"id": "s-gdzie-sprawdzic", "block": 1, "blockName": "Wymagania ogólne", "topic": "Podstawy prawne", "adrRef": "ADR 1.1 / zrodla", "why": "Kierowca nie musi pamiętać wszystkiego — musi wiedzieć, gdzie sprawdzić. Wykaz krajów ADR, dodatkowe wymagania krajowe i wykaz tuneli: masteradr.pl/kraje. Tabela A, instrukcje pisemne i formularz multimodalny do pobrania: doradca-adr.com/dokumenty-do-pobrania. Wątpliwości w firmie rozstrzyga doradca DGSA."}, {"id": "s-grupa-pakowania-ktore-klasy", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR 2.1.1.3", "why": "Grup pakowania NIE MAJĄ klasy 1, 2, 5.2, 6.2, 7 oraz przedmioty. Jeśli w dokumencie przy klasie 2 widzisz grupę pakowania — to błąd. Grupa pakowania określa natężenie zagrożenia dominującego: I duże, II średnie, III małe."}, {"id": "s-grupa-pakowania-natezenie", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR 2.1.1.3", "why": "Grupa pakowania = natężenie zagrożenia dominującego. I = duże, II = średnie, III = małe. Benzyna UN 1203 = II. Olej napędowy UN 1202 = III. Im niższa cyfra rzymska, tym groźniejszy towar."}, {"id": "s-ino-uzupelnienie", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR 3.1.2.8", "why": "I.N.O. = inaczej nie określony. Wymaga uzupełnienia o nazwy techniczne składników w nawiasie, np. UN 1964 WĘGLOWODORY GAZOWE, MIESZANINA SPRĘŻONA I.N.O (zawiera wodór i argon) 2.1 (B/D). Bez tego zapis jest niekompletny."}, {"id": "s-jtr-paliwo-zestaw", "block": 1, "blockName": "Wymagania ogólne", "topic": "Jednostka i sposoby przewozu", "adrRef": "ADR 1.1.3.3 / 1.2.1", "why": "Limit 1500 l dotyczy CAŁEJ jednostki transportowej, nie każdego pojazdu osobno. Ciągnik 1000 l + naczepa 400 l = 1400 l na jednostkę — mieści się. Ale uwaga: na przyczepie limit to dodatkowo max 500 l."}, {"id": "s-jtr-wyposazenie-liczba", "block": 1, "blockName": "Wymagania ogólne", "topic": "Jednostka i sposoby przewozu", "adrRef": "ADR 8.1.5 / 1.2.1", "why": "Pułapka: klin pod koła liczy się NA KAŻDY POJAZD (ciągnik + naczepa = 2 kliny), ale stojące znaki ostrzegawcze liczy się NA JEDNOSTKĘ TRANSPORTOWĄ (zestaw = 2 znaki, nie 4). Ciągnik z naczepa to jedna jednostka, ale dwa pojazdy."}, {"id": "s-kanistry-przekroczenie", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 1.1.3.3", "why": "Limit paliwa w zbiornikach dodatkowych (kanistrach) to 60 l. Przekroczenie tego limitu oznacza, ze wyłączenie 1.1.3.3 nie przysługuje dla nadwyżki — trzeba stosować przepisy ADR."}, {"id": "s-klasa9-co-tam", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 2.2.9", "why": "Klasa 9 to \"różne\" — wpadają tu towary bez wspólnego mianownika: azbest, materiały w podwyższonej temperaturze (stałe >240 st. C, ciekłe >100 st. C), akumulatory litowe, przedmioty ratownicze, materiały zagrażające środowisku wodnemu (UN 3077/3082)."}, {"id": "s-kod-klasyfikacyjny", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR 2.1.1.2", "why": "Zagrożenie dodatkowe określane jest kodem literowym: F = palne, T = trujące. Kod klasyfikacyjny mówi więcej niż sama klasa — np. gaz z kodem TF to gaz trujący i palny jednocześnie. To druga nalepka w dokumencie przewozowym."}, {"id": "s-kod-opakowania-y", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt opakowania", "adrRef": "ADR 6.1.2", "why": "Litera na drugim miejscu kodu opakowania: X = dla I, II i III grupy pakowania; Y = dla II i III; Z = tylko dla III. Opakowanie Y nie nadaje się do towaru I grupy pakowania."}, {"id": "s-kto-klasyfikuje-nie-ty", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR czesc 2", "why": "Za klasyfikację odpowiada PRODUCENT, NADAWCA i IPO (dla klasy 7 — PAA). Kierowca NIE klasyfikuje towaru. Jeśli masz wątpliwości co do klasyfikacji, nie zgadujesz — pytasz nadawcę albo doradcę DGSA."}, {"id": "s-ktora-edycja", "block": 1, "blockName": "Wymagania ogólne", "topic": "Podstawy prawne", "adrRef": "ADR 1.6", "why": "ADR nowelizowany jest co 2 lata, nowe przepisy wchodzą 1 stycznia roku NIEPARZYSTEGO. Edycje: 2021, 2023, 2025, 2027... Wiedza sprzed dwóch lat może być już nieaktualna — dlatego każde szkolenie i materiał trzeba sprawdzić pod kątem edycji."}, {"id": "s-ladowanie-3-8", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o załadunku", "adrRef": "ADR 7.5.2.1", "why": "W ADR większość klas można ładować razem przy prawidłowym opakowaniu (inaczej niż w transporcie morskim IMDG). Zakazy 7.5.2.1 dotyczą w uproszczeniu klasy 1 oraz 4.1+1 i 5.2+1 o właściwościach wybuchowych."}, {"id": "s-ladowanie-klasa1", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o załadunku", "adrRef": "ADR 7.5.2.1", "why": "Zakazy ładowania razem koncentrują się na klasie 1 (materiały wybuchowe). Wyjątkiem jest podklasa 1.4S, która ma najłagodniejszy reżim. Szczegóły w tabeli 7.5.2.1."}, {"id": "s-luzem-czy-wolno", "block": 1, "blockName": "Wymagania ogólne", "topic": "Jednostka i sposoby przewozu", "adrRef": "ADR kol. 10/17 Tabeli A", "why": "Przewóz luzem NIE jest dozwolony domyślnie. Wolno tylko wtedy, gdy w tabeli A w kolumnie 10 lub 17 wskazany jest przepis szczególny BK1, BK2, BK3, VC1, VC2 lub VC3. Przepisy BK wskazują specjalny rodzaj kontenera. Przykład: UN 3257 (materiał o podwyższonej temperaturze ciekły) może być luzem na podstawie VC3."}, {"id": "s-multimodal-przepisy", "block": 1, "blockName": "Wymagania ogólne", "topic": "Podstawy prawne", "adrRef": "ADR 1.1.4.2.1 / IMDG", "why": "Poza ADR (droga) obowiązują: RID (kolej), ADN (śródlądowy), IMDG (morski), ICAO TI (lotniczy). Przy przewozie multimodalnym przesyłki mogą być oznakowane wg kodeksu morskiego lub lotniczego — wtedy w dokumencie zapis \"Przewóz zgodny z 1.1.4.2.1\". Przed przewozem morskim wymagany jest certyfikat pakowania kontenera."}, {"id": "s-odstepstwa-umowy", "block": 1, "blockName": "Wymagania ogólne", "topic": "Podstawy prawne", "adrRef": "ADR 1.5", "why": "Kraje mogą wprowadzać dodatkowe wymagania (np. przejazd tunelami, okresowe zakazy ruchu) oraz umowy specjalne dopuszczające odstępstwa od przepisów. Odstępstwa nie mogą trwać dłużej niż 5 lat. Wykaz na masteradr.pl/kraje."}, {"id": "s-okres-przejsciowy", "block": 1, "blockName": "Wymagania ogólne", "topic": "Podstawy prawne", "adrRef": "ADR 1.6", "why": "Nowe przepisy wchodzą 1 stycznia roku nieparzystego, ale do końca czerwca obowiązuje okres przejściowy — można stosować \"stara\" LUB \"nowa\" wersje przepisów. Od 1 lipca obowiązuje już tylko nowa."}, {"id": "s-oznakowanie-decyzja", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Oznakowanie pojazdu w praktyce", "adrRef": "ADR 5.3", "why": "Sposób oznakowania zależy od sposobu przewozu. Sztuki przesyłki: tablice gładkie (bez numerów) przód i tył, BEZ nalepek na pojeździe. Luzem lub cysterna: tablice z numerami przód i tył + nalepki z trzech stron (oba boki i tył). Kontener-cysterna: nalepki z 4 stron."}, {"id": "s-paliwo-limity", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 1.1.3.3", "why": "Wyłączenie 1.1.3.3 dla paliwa w zbiornikach pojazdu: do 1500 l na jednostkę transportową, nie więcej niż 500 l na przyczepie, w kanistrach nie więcej niż 60 l."}, {"id": "s-podklasa-4", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 2.2.41-43", "why": "Klasa 4: 4.1 zapalne stałe i samoreaktywne, 4.2 podatne na samozapalenie (piroforyczne, fosfor biały, rozdrobnione metale), 4.3 wydzielają z wodą gazy palne. Skutek praktyczny: 4.3 MUSZĄ być w pojazdach zamkniętych, a uwolniony materiał trzyma się w stanie suchym pod przykryciem."}, {"id": "s-podklasa-5", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 2.2.51-52", "why": "Klasa 5.1 (utleniające) same nie muszą się palić, ale WZMAGAJĄ palenie. Nie wolno ich mieszać z materiałami zapalnymi — np. trocinami. W kontakcie mogą gwałtownie reagować, wybuchać, powodować pożar. 5.2 to nadtlenki organiczne (typy A-F), niektóre wybuchowe."}, {"id": "s-podklasa-6-pulapka", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 2.2.61-62", "why": "Klasa 6.1 = trujące (zatrucie przez połknięcie, wdychanie, skórę). Klasa 6.2 = zakaźne (odpady medyczne, wirusy, bakterie, priony). PUŁAPKA: NIE występują materiały jednocześnie zakaźne I trujące — takie połączenie nie istnieje w ADR."}, {"id": "s-podklasa-gazu", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 2.2.2", "why": "Klasa 2: 2.1 gazy palne (propan), 2.2 gazy niepalne i nietrujące — MOGĄ BYĆ DUSZĄCE (azot, argon), 2.3 gazy trujące (chlor). Pułapka: 2.2 nie jest \"bezpieczny\" — dusi, wypierając tlen. Dlatego przy gazach unika się zagłębień terenu."}, {"id": "s-pozycja-grupowa", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR 3.1.2", "why": "Numer UN może być przypisany do JEDNEJ substancji (UN 1090 ACETON) albo do POZYCJI GRUPOWEJ — kilku towarów o podobnych właściwościach (UN 1263 FARBA). Przy pozycji grupowej pod jednym numerem UN kryją się różne produkty."}, {"id": "s-prozne-nalepki", "block": 1, "blockName": "Wymagania ogólne", "topic": "Wyłączenia w praktyce", "adrRef": "ADR 5.1.3", "why": "Próżne, nieoczyszczone opakowania pozostają oznakowane tak jak w stanie ładownym. Nie usuwa się nalepek ostrzegawczych ani numerów UN. Zdejmuję się je dopiero po całkowitym oczyszczeniu (robi to rozładowca)."}, {"id": "s-przypisz-klase", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasyfikacja", "adrRef": "ADR czesc 2", "why": "Rozpoznanie klasy po towarze to podstawa. Benzyna i olej napędowy = klasa 3 (ciecze zapalne). Propan/butan = klasa 2 (gazy). Kwas siarkowy = klasa 8 (żrące). Baterie litowe = klasa 9. Azotan amonu = klasa 5.1 (utleniający)."}, {"id": "s-sposob-przewozu-rozpoznanie", "block": 1, "blockName": "Wymagania ogólne", "topic": "Jednostka i sposoby przewozu", "adrRef": "ADR 1.2.1 / 5.3", "why": "Rozpoznanie sposobu przewozu decyduje o oznakowaniu pojazdu. Sztuki przesyłki to opakowania: kanistry, bębny, butle, DPPL, worki, BIG-BAGi, wiązki. Luzem to NIEOPAKOWANE materiały stałe, np. zużyte akumulatory. Cysterna to zbiornik z wyposażeniem."}, {"id": "s-swiadectwo-kiedy", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Praca z dokumentem", "adrRef": "ADR 9.1.3", "why": "Świadectwo dopuszczenia (\"czerwony pasek\") wymagane jest dla pojazdów EX/II i EX/III (klasa 1), FL i AT (cysterny) oraz MEMU. Pojazdy przewożące sztuki przesyłki (poza wybuchowymi) i luzem NIE muszą go mieć — np. butle z gazem, DPPL, kanistry."}, {"id": "s-tablica-268-1017", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.3", "why": "Numer 268 = gaz trujący żrący. Cyfra 2 = emisja gazu, 6 = działanie trujące, 8 = działanie żrące. UN 1017 = chlor. Wymagana maska ucieczkowa (nalepka 2.3)."}, {"id": "s-tablica-33-1203", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.3", "why": "Górny numer 33: cyfra 3 = zapalność cieczy, podwojenie = nasilenie, czyli materiał łatwo zapalny ciekły o temperaturze zapłonu poniżej 23 st. C. Dolny 1203 = benzyna silnikowa."}, {"id": "s-tablica-90-3082", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.3", "why": "Numer 90 = materiał zagrażający środowisku, różne materiały niebezpieczne. UN 3082 = materiał zagrażający środowisku wodnemu, ciekły, i.n.o. (klasa 9)."}, {"id": "s-tablica-sklad-cyfr", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.3", "why": "Numer rozpoznawczy składa się z cyfr o stalym znaczeniu: 2 emisja gazu, 3 zapalność cieczy, 4 zapalność ciał stałych, 5 utleniające, 6 trujące/zakaźne, 7 promieniotwórcze, 8 żrące, 9 gwałtowna reakcja. Składając je czytasz zagrożenie bez tabeli."}, {"id": "s-tablica-x-woda", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.3", "why": "Litera X przed numerem = materiał reaguje niebezpiecznie z wodą. Woda może być użyta tylko za zgoda specjalistów. To informacja ratująca życie przy gaszeniu."}, {"id": "s-tablica-zero", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt tablicy", "adrRef": "ADR 5.3.2.3", "why": "Zero na drugiej pozycji oznacza brak zagrożenia dodatkowego i brak nasilenia. Towar zwykle należy do II lub III grupy pakowania. Numer 30 = materiał zapalny ciekły (23-60 st. C)."}, {"id": "s-temp-kontrolowana-kiedy", "block": 2, "blockName": "Główne zagrożenia", "topic": "Klasy zagrożeń", "adrRef": "ADR 7.1.7", "why": "Temperatury kontrolowanej mogą wymagać klasy 4.1 (samoreaktywne) i 5.2 (nadtlenki organiczne) — reakcja egzotermiczna. Wtedy: termometr z 2 czujnikami, sprawdzanie co 4-6 h, rejestracja, procedura na wypadek utraty kontroli temperatury. Zapis w dokumencie: TEMPERATURA KONTROLOWANA / TEMPERATURA AWARYJNA."}, {"id": "s-tunel-b", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o tunelu", "adrRef": "ADR 1.9.5", "why": "Kod (B) = zakaz w tunelach B, C, D i E. Przejechać można tylko tunelem kategorii A (nieoznakowany lub ze znakiem D-37). To najbardziej restrykcyjny kod dla przewozu."}, {"id": "s-tunel-de-cysterna", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o tunelu", "adrRef": "ADR 1.9.5", "why": "Kod (D/E) czytamy: D dotyczy cysterny i luzem, E dotyczy sztuk przesyłki. Cysterna z kodem D nie może wjechać do tunelu D ani E. Do C, B i A może."}, {"id": "s-tunel-de-sztuki", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o tunelu", "adrRef": "ADR 1.9.5", "why": "Kod (D/E): przy przewozie w sztukach przesyłki obowiązuje E — zakaz tylko w tunelu kategorii E. Do D, C, B i A wolno."}, {"id": "s-tunel-gdzie-kod", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o tunelu", "adrRef": "ADR kol. 15", "why": "Kod tunelowy towaru znajdziesz w dokumencie przewozowym (w nawiasie na końcu zapisu) oraz w tabeli A w kolumnie 15. Kategorie tunelu na drodze odczytasz z tabliczki pod znakiem B-13a."}, {"id": "s-tunel-lq", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o tunelu", "adrRef": "ADR 3.4 / 1.9.5", "why": "Jednostka powyżej 12 t DMC przewożąca powyżej 8 t brutto towarów w ilościach ograniczonych (LQ) musi być oznakowana znakiem LQ i NIE MOŻE wjeżdżać do tunelu kategorii E."}, {"id": "s-tunel-minus", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Decyzja o tunelu", "adrRef": "ADR 1.9.5 / kol. 15", "why": "Kod \"(-)\" w kolumnie 15 tabeli A oznacza brak ograniczeń tunelowych — wolno wjechać do każdego tunelu, łącznie z E. Dotyczy m.in. UN 2814, 2900, 2919, 3166, 3171, 3331, 3359, 3373, 3549."}, {"id": "s-un-3077-3082", "block": 3, "blockName": "Ochrona środowiska", "topic": "Materiały zagrażające środowisku", "adrRef": "ADR 3.2.1", "why": "Materiał zagrażający środowisku: UN 3077 gdy STAŁY, UN 3082 gdy CIEKŁY. Oba należą do klasy 9. Numer rozpoznawczy zagrożenia dla nich to 90."}, {"id": "s-uprawnienia-cysterna", "block": 1, "blockName": "Wymagania ogólne", "topic": "Zakres uprawnień", "adrRef": "ADR 8.2.1", "why": "ADR podstawowy obejmuje cysterny stałe i odejmowalne do 1000 l oraz kontenery-cysterny do 3000 l. Powyżej tych progów wymagany jest kurs specjalistyczny cysterny (od 1 m3 = 1000 l)."}, {"id": "s-uprawnienia-klasy", "block": 1, "blockName": "Wymagania ogólne", "topic": "Zakres uprawnień", "adrRef": "ADR 8.2.1", "why": "ADR podstawowy pozwala przewozić wszystkie klasy POZA 1 (wybuchowe) i 7 (promieniotwórcze), w sztukach przesyłki oraz luzem. Klasa 1 i 7 wymagaja osobnych kursów specjalistycznych."}, {"id": "s-wiatr-opary", "block": 5, "blockName": "Po wypadku", "topic": "Reakcja po wypadku", "adrRef": "ADR 5.4.3.4", "why": "Należy unikać wdychania oparów, dymu, pyłu i pary poprzez pozostawanie po stronie NAWIETRZNEJ — czyli tam, skąd wieje wiatr. Wiatr wieje od Ciebie w stronę zdarzenia, nie odwrotnie."}, {"id": "s-wypadek-sekwencja", "block": 5, "blockName": "Po wypadku", "topic": "Reakcja po wypadku", "adrRef": "ADR 5.4.3.4", "why": "Sekwencja z instrukcji pisemnej: najpierw zabezpiecz pojazd (zahamuj, wyłącz silnik, odłącz akumulator), potem załóż kamizelkę i ustaw znaki, powiadom służby, zapewnij ratownikom dostęp do dokumentów. Oddał się po stronie nawietrznej."}, {"id": "s-wyposazenie-ilosci", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór wyposażenia", "adrRef": "ADR 8.1.5", "why": "Na każdego członka załogi: kamizelka, latarka, rękawice, ochrona oczu, maska ucieczkowa (gdy wymagana). Po 1 sztuce w pojeździe niezależnie od załogi: płyn do płukania oczu, łopata, osłona kanalizacji, pojemnik. Klin — dla każdego pojazdu. Znaki stojące — 2 na jednostkę."}, {"id": "s-wyposazenie-klasa2-3", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór wyposażenia", "adrRef": "ADR 8.1.5.3", "why": "Nalepka 2.3 (gazy trujące) wymaga maski ucieczkowej dla każdego członka załogi. Jednocześnie płyn do płukania oczu NIE jest wymagany przy nalepkach 1, 1.4, 1.5, 1.6, 2.1, 2.2, 2.3. Łopata też nie — 2.3 nie jest na liście 3/4.1/4.3/8/9."}, {"id": "s-wyposazenie-klasa3", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Dobór wyposażenia", "adrRef": "ADR 8.1.5", "why": "Nalepka 3 należy do grupy 3, 4.1, 4.3, 8, 9 — wymagana łopata, osłona otworów kanalizacyjnych i pojemnik do zbierania pozostałości (po 1 sztuce). Płyn do płukania oczu też wymagany (nie jest na liście wyłączeń 1/2.x)."}, {"id": "s-x-opakowanie-vs-tablica", "block": 2, "blockName": "Główne zagrożenia", "topic": "Odczyt opakowania", "adrRef": "ADR 5.3.2.3 / 6.1.2", "why": "Pułapka egzaminacyjna: litera X ma DWA różne znaczenia. Na tablicy pomarańczowej (przed numerem zagrożenia) = niebezpieczna reakcja z wodą. W kodzie opakowania = mocne opakowanie do I, II i III grupy pakowania. To nie ma ze soba związku."}, {"id": "s-zgloszenie-sluzbom", "block": 5, "blockName": "Po wypadku", "topic": "Reakcja po wypadku", "adrRef": "procedury krajowe", "why": "Kolejność informacji dla służb: miejsce zdarzenia, rodzaj zdarzenia, skutki, liczba ofiar, rozmiar (ile pojazdów/osób), numery UN, sposób przewozu (luzem/cysterna), ilość towaru, czy nastąpiło uwolnienie. Numer UN odczytasz z tablicy lub dokumentu."}, {"id": "s-znak-srodowisko-prog", "block": 3, "blockName": "Ochrona środowiska", "topic": "Materiały zagrażające środowisku", "adrRef": "ADR 5.2.1.8.1", "why": "Znak materiału zagrażającego środowisku (ryba i uschnięte drzewo) umieszcza się na opakowaniach WIĘKSZYCH niż 5 kg lub 5 litrów. Poniżej tego progu znak nie jest wymagany."}, {"id": "s-znak-temperatura-prog", "block": 3, "blockName": "Ochrona środowiska", "topic": "Materiały zagrażające środowisku", "adrRef": "ADR 5.2.1.8.1", "why": "Znak podwyższonej temperatury (czerwony trójkąt z termometrem) dotyczy materiałów stałych powyżej 240 st. C i ciekłych powyżej 100 st. C. Zagrożenie poparzeniem — unikać kontaktu z gorącymi częściami jednostki i z uwolnionym materiałem."}, {"id": "s-zrodla-zaplonu-decyzja", "block": 5, "blockName": "Po wypadku", "topic": "Reakcja po wypadku", "adrRef": "ADR 5.4.3.4", "why": "Po wypadku należy unikać źródeł zapłonu: nie palić, nie używać e-papierosów, NIE WŁĄCZAĆ żadnych urządzeń elektrycznych. Telefon jako latarka to urządzenie elektryczne — użyj latarki z wyposażenia ADR (jest przystosowana)."}, {"id": "x-baterie-sodowe-2025", "block": 2, "blockName": "Główne zagrożenia", "topic": "Zmiany ADR 2025", "adrRef": "ADR 2025 UN 3551/3552", "why": "ROZSZERZENIE (poza kompendium): ADR 2025 wprowadza baterie sodowo-jonowe — UN 3551 (z elektrolitem organicznym) i UN 3552 (zapakowane z urządzeniem lub w urządzeniu). Kod klasyfikacyjny M4 obejmuje teraz baterie litowe i sodowo-jonowe. DO WERYFIKACJI."}, {"id": "x-dokument-kabina-2025", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Zmiany ADR 2025", "adrRef": "ADR 5.4.1 (zmiana 2025)", "why": "ROZSZERZENIE (poza kompendium): według źródeł dot. ADR 2025 od 1 lipca 2025 dokumenty przewozowe muszą znajdować się w kabinie kierowcy. Kompendium ADR 2023 tego nie zawiera. DO WERYFIKACJI."}, {"id": "x-kamizelka-eniso20471-2025", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Zmiany ADR 2025", "adrRef": "ADR 2025, 8.1.5 + EN ISO 20471:2023", "why": "ROZSZERZENIE (poza kompendium): ADR 2025 doprecyzowuje, ze kamizelka ostrzegawcza w wyposażeniu pojazdu ma spełniać normę EN ISO 20471:2023 (lepsza widoczność w słabym świetle). DO WERYFIKACJI DGSA."}, {"id": "x-lq-szkolenie-2025", "block": 1, "blockName": "Wymagania ogólne", "topic": "Zmiany ADR 2025", "adrRef": "ADR 8.2.3 (doprecyzowanie 2025)", "why": "ROZSZERZENIE (poza kompendium): według źródeł dot. ADR 2025 doprecyzowano wymóg szkolenia załogi przewożącej towary w ilościach ograniczonych (LQ). DO WERYFIKACJI — kompendium ADR 2023 tego nie precyzuje."}, {"id": "x-pojazdy-baterie-2025", "block": 2, "blockName": "Główne zagrożenia", "topic": "Zmiany ADR 2025", "adrRef": "ADR 2025 UN 3556-3558", "why": "ROZSZERZENIE (poza kompendium): ADR 2025 wprowadza numery UN 3556 (pojazd napędzany bateria litowo-jonowa), UN 3557 (litowo-metalowa), UN 3558 (sodowo-jonowa). Stosuje się nową instrukcję pakowania P912. DO WERYFIKACJI."}, {"id": "x-segregacja-klasa1-uproszczenie-2025", "block": 4, "blockName": "Środki bezpieczeństwa", "topic": "Zmiany ADR 2025", "adrRef": "ADR 2025, 7.5.2.2", "why": "ROZSZERZENIE (poza kompendium): ADR 2025 upraszcza matryce mieszanego ładowania, szczególnie dla klasy 1 (materiały wybuchowe). Zakres specjalistyczny. DO WERYFIKACJI DGSA."}, {"id": "x-sp677-baterie-uszkodzone-2025", "block": 1, "blockName": "Wymagania ogólne", "topic": "Zmiany ADR 2025", "adrRef": "ADR 2025, SP 677 (3.3)", "why": "ROZSZERZENIE (poza kompendium): ADR 2025 wprowadza przepis szczególny SP 677 dla baterii litowych i sodowo-jonowych uszkodzonych w sposób krytyczny. Takie baterie przewozi się jako kategoria transportową 0 — nigdy nie podlegają wyłączeniu 1.1.3.6. DO WERYFIKACJI DGSA."}];
